interface IOracleProvider {
    function sync() external returns (OracleVersion memory);
    function currentVersion() external view returns (OracleVersion memory);
    function atVersion(uint256 oracleVersion) external view returns (OracleVersion memory);
}

struct OracleVersion {
    uint256 version;
    uint256 timestamp;
    int256 price;
}

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property() public {
        // Read oracle() directly; in the reference it returns the non-zero address
        // of the IController passed during construction (which is always a contract
        // since it is deployed by the test), but the mutant returns address(0).
        // The assertion verifies that the returned address is a non-zero contract.
        address oracleAddr = address(c.oracle());
        assertTrue(oracleAddr != address(0) && oracleAddr.code.length > 0);
    }
