contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 addrNum) public {
        // Bound addrNum to a range that will produce a contract address, not zero
        address oracleAddr = address(uint160(bound(addrNum, 1, type(uint160).max)));
        vm.assume(oracleAddr != address(0));
        // Deploy a minimal contract at that address to ensure isContract passes
        // We use a helper that implements IOracleProvider
        Helper helper = new Helper();
        vm.etch(oracleAddr, address(helper).code);
        // Expect oracle() to not revert and return a non-zero address
        // The reference returns the stored oracle, mutant returns 0 which fails isContract
        bool success = false;
        try c.oracle() {
            success = true;
        } catch {
            success = false;
        }
        assertTrue(success);
    }
}

