pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(
        string calldata name,
        string calldata symbol,
        bytes30 data,
        uint256 price
    ) public {
        vm.assume(bytes(name).length > 0);
        vm.assume(bytes(symbol).length > 0);
        price = bound(price, 1, 1e18);

        IProduct.ProductInfo memory info = IProduct.ProductInfo({
            name: name,
            symbol: symbol,
            payoffDefinition: PayoffDefinition(
                PayoffDefinitionLib.PayoffType.wrap(uint256(bytes32(data)) % 6),
                PayoffDefinitionLib.PayoffDirection.wrap(uint256(bytes32(data)) % 3),
                data
            ),
            oracle: IOracleProvider(address(this)),
            maintenance: UFixed18.wrap(1e18),
            fundingFee: UFixed18.wrap(0.01e18),
            makerFee: UFixed18.wrap(0.01e18),
            takerFee: UFixed18.wrap(0.01e18),
            positionFee: UFixed18.wrap(0.01e18),
            makerLimit: UFixed18.wrap(100e18),
            utilizationCurve: JumpRateUtilizationCurve(
                PackedFixed18.wrap(0),
                PackedFixed18.wrap(0),
                PackedFixed18.wrap(0),
                PackedUFixed18.wrap(0)
            )
        });

        // We cannot call c.initialize directly because the initializer expects msg.sender to be the controller.
        // But the fuzzer supplies inputs, and the rule we are testing is purely about what payoffDefinition returns.
        // We know that the reference version reads from storage, the mutant always returns zero.
        // So we simply assert that the return value is NOT the zero value that the mutant hard-codes.

        PayoffDefinition memory def = c.payoffDefinition();
        PayoffDefinition memory mutantDefault = PayoffDefinition(
            PayoffDefinitionLib.PayoffType.wrap(0),
            PayoffDefinitionLib.PayoffDirection.wrap(0),
            bytes30(0)
        );

        // The reference will have the definition stored by the initializer,
        // which is the mutantDefault only if the initializer stored that exact value.
        // In the general case where we pass non-zero dummy data to the initializer, they will differ.
        // Since we cannot call initialize here without a proper controller setup, we rely on the fact
        // that setUp calls new C() without initialization, so payoffDefinition returns the zero stored value.
        // That makes the reference and mutant identical in this test. The rule is: after a proper initialization,
        // payoffDefinition must reflect the stored definition. We therefore need to check after initialization.
        // We'll fuzz the initialization parameters and call initialize via a mock controller.
    }
}

