pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint8 payoffType, uint8 payoffDirection, bytes30 data) public {
        // Bind fuzzed values to valid PayoffDefinition types
        vm.assume(payoffType <= 3);  // valid PayoffType range
        vm.assume(payoffDirection <= 1); // valid PayoffDirection range

        // Create ProductInfo with the fuzzed PayoffDefinition
        IProduct.ProductInfo memory info;
        info.name = "test";
        info.symbol = "TST";
        info.payoffDefinition = PayoffDefinition(
            PayoffDefinitionLib.PayoffType(payoffType),
            PayoffDefinitionLib.PayoffDirection(payoffDirection),
            data
        );
        info.oracle = IOracleProvider(address(this)); // dummy address

        // Initialize the product - this will succeed if payoffDefinition is valid
        c.initialize(info);

        // Retrieve the stored payoff definition
        PayoffDefinition memory stored = c.payoffDefinition();

        // Assert that the stored payoff definition matches what was passed to initialize
        assertTrue(
            stored.payoffType == PayoffDefinitionLib.PayoffType(payoffType) &&
            stored.payoffDirection == PayoffDefinitionLib.PayoffDirection(payoffDirection) &&
            stored.data == data
        );
    }
}

interface IProduct {
    struct ProductInfo {
        string name;
        string symbol;
        PayoffDefinition payoffDefinition;
        IOracleProvider oracle;
        UFixed18 maintenance;
        UFixed18 fundingFee;
        UFixed18 makerFee;
        UFixed18 takerFee;
        UFixed18 positionFee;
        UFixed18 makerLimit;
        JumpRateUtilizationCurve utilizationCurve;
    }
}

interface IOracleProvider {
    struct OracleVersion {
        uint256 version;
        uint256 timestamp;
        Fixed18 price;
    }
}

type UFixed18 is uint256;
type Fixed18 is int256;

struct PayoffDefinition {
  PayoffDefinitionLib.PayoffType payoffType;
  PayoffDefinitionLib.PayoffDirection payoffDirection;
  bytes30 data;
}

library PayoffDefinitionLib {
    enum PayoffType { PASSTHROUGH, BINARY, CALL, PUT }
    enum PayoffDirection { LONG, SHORT }

    function valid(PayoffDefinition memory self) internal pure returns (bool) {
        return uint8(self.payoffType) <= 3 && uint8(self.payoffDirection) <= 1;
    }

    function transform(PayoffDefinition memory self, Fixed18 price) internal pure returns (Fixed18) {
        return price;
    }
}

struct JumpRateUtilizationCurve {
    PackedFixed18 minRate;
    PackedFixed18 maxRate;
    PackedFixed18 targetRate;
    PackedUFixed18 targetUtilization;
}

type PackedFixed18 is int128;
type PackedUFixed18 is uint128;

using PayoffDefinitionLib for PayoffDefinition global;

