pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(bytes30 data, int256 price, int8 payoffTypeInt, int8 payoffDirectionInt) public {
        // Restrict payoffType and payoffDirection to valid enum values 0 or 1
        vm.assume(payoffTypeInt == 0 || payoffTypeInt == 1);
        vm.assume(payoffDirectionInt == 0 || payoffDirectionInt == 1);
        PayoffDefinitionLib.PayoffType pType = PayoffDefinitionLib.PayoffType(uint8(payoffTypeInt));
        PayoffDefinitionLib.PayoffDirection pDir = PayoffDefinitionLib.PayoffDirection(uint8(payoffDirectionInt));

        // Construct a valid PayoffDefinition payload
        bytes memory payload = abi.encode(PayoffDefinition(pType, pDir, data));

        // Use a proxy to call the internal _payoffDefinition.store() by deploying a minimal init contract
        // But C has no external setter for payoffDefinition after initialization.
        // We must utilize the initializer in setUp, but that would hardcode the test.
        // Instead, we can bypass initialization by driving through the public payoffDefinition() getter
        // and comparing with a known value? No, we need to set the storage first.
        // C is not initialized, so we must initialize it with arbitrary values.
        // The fuzzer must vary the stored PayoffDefinition, which is only set during initialize().
        // We will call initialize with fuzzed parameters and then check payoffDefinition().

        // Build ProductInfo with fuzzed parameters
        IProduct.ProductInfo memory info;
        info.name = "test";
        info.symbol = "TST";
        info.payoffDefinition = PayoffDefinition(pType, pDir, data);
        info.oracle = IOracleProvider(address(0x1)); // simple address, oracle not used in this property
        info.maintenance = UFixed18.wrap(1000000000000000000); // 1e18
        info.fundingFee = UFixed18.wrap(0);
        info.makerFee = UFixed18.wrap(0);
        info.takerFee = UFixed18.wrap(0);
        info.positionFee = UFixed18.wrap(0);
        info.makerLimit = UFixed18.wrap(100000000000000000000); // 100e18
        info.utilizationCurve = JumpRateUtilizationCurve({
            minRate: PackedFixed18.wrap(int128(100000000000000000)),
            maxRate: PackedFixed18.wrap(int128(500000000000000000)),
            targetRate: PackedFixed18.wrap(int128(200000000000000000)),
            targetUtilization: PackedUFixed18.wrap(uint128(800000000000000000))
        });

        // We cannot call initialize directly because it requires the caller to be the controller (IController)
        // So we deploy a minimal controller that allows initialization.
        // Since the adversarial counterparty rule requires deploying helper when needed, here we need a controller.
    }
}

