pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public {
        c = new C();
    }

    function testFuzz_property(
        uint8 payoffTypeRaw,
        uint8 payoffDirectionRaw,
        bytes30 data
    ) public {
        // bind to valid enum ranges: PayoffType is 0..2, PayoffDirection is 0..1 (unknown enums so keep 0..255 and rely on valid() to pass)
        vm.assume(payoffTypeRaw <= 2);
        vm.assume(payoffDirectionRaw <= 1);

        // construct a PayoffDefinition fuzzed by the test inputs
        // (since we cannot directly call the original internal _payoffDefinition.read() before
        // the initialization, we initialize product with these values)
        address oracle = address(new OracleMock());
        C.ProductInfo memory info;
        info.name = "test";
        info.symbol = "T";
        info.oracle = IOracleProvider(oracle);
        // fuzz payoffDefinition
        PayoffDefinitionLib.PayoffType payoffType = PayoffDefinitionLib.PayoffType(payoffTypeRaw);
        PayoffDefinitionLib.PayoffDirection payoffDirection = PayoffDefinitionLib.PayoffDirection(payoffDirectionRaw);
        if (payoffDirection == PayoffDefinitionLib.PayoffDirection(0)) {
            vm.assume(payoffType != PayoffDefinitionLib.PayoffType(1));
        } else {
            vm.assume(payoffType != PayoffDefinitionLib.PayoffType(0));
        }
        info.payoffDefinition = PayoffDefinition({
            payoffType: payoffType,
            payoffDirection: payoffDirection,
            data: data
        });
        info.maintenance = UFixed18.wrap(1000);
        info.fundingFee = UFixed18.wrap(0);
        info.makerFee = UFixed18.wrap(0);
        info.takerFee = UFixed18.wrap(0);
        info.positionFee = UFixed18.wrap(0);
        info.makerLimit = UFixed18.wrap(1000000);
        info.utilizationCurve = JumpRateUtilizationCurve({
            minRate: PackedFixed18.wrap(1),
            maxRate: PackedFixed18.wrap(1),
            targetRate: PackedFixed18.wrap(1),
            targetUtilization: PackedUFixed18.wrap(1)
        });

        // we need the controller to be the caller of initialize
        address controllerAddr = address(new InitializerController());
        vm.prank(controllerAddr);
        c.initialize(info);

        // now call payoffDefinition (public)
        PayoffDefinition memory result = c.payoffDefinition();

        // reference property: payoffDefinition() must always return a struct exactly matching the stored one
        // the stored one is info.payoffDefinition.
        bool sameType = result.payoffType == info.payoffDefinition.payoffType;
        bool sameDirection = result.payoffDirection == info.payoffDefinition.payoffDirection;
        bool sameData = result.data == info.payoffDefinition.data;

        assertTrue(sameType && sameDirection && sameData);
    }
}

